import { SpeciesId } from './types';

/**
 * Pre-projected North America basemap (Natural Earth 1:50m) and native species range
 * polygons (USGS Elbert L. Little "Atlas of United States Trees") in a canonical
 * [0, 1000] x [0, 942] North America Albers Equal-Area Conic coordinate system
 * (central meridian 98°W, standard parallels 27°N & 53°N, origin latitude 40°N).
 */
export const LOCATOR_MAP_WIDTH = 1000;
export const LOCATOR_MAP_HEIGHT = 942;

const DEG2RAD = Math.PI / 180;
const LON0 = -98 * DEG2RAD;
const LAT0 = 40 * DEG2RAD;
const PHI1 = 27 * DEG2RAD;
const PHI2 = 53 * DEG2RAD;
const ALBERS_N = 0.5 * (Math.sin(PHI1) + Math.sin(PHI2));
const ALBERS_C = Math.cos(PHI1) * Math.cos(PHI1) + 2 * ALBERS_N * Math.sin(PHI1);
const ALBERS_RHO0 = Math.sqrt(ALBERS_C - 2 * ALBERS_N * Math.sin(LAT0)) / ALBERS_N;

const X_MIN = -0.53;
const X_SPAN = 1.04;
const Y_MIN = -0.55;
const Y_SPAN = 0.98;

export interface ProjectedLocatorPoint {
  x: number;
  y: number;
  inFrame: boolean;
  clampedX: number;
  clampedY: number;
}

/**
 * Projects geographic (latitude, longitude) in degrees into the [0, 1000] x [0, 942]
 * North America Albers Equal-Area Conic locator map coordinate frame.
 */
export function projectToLocatorMap(
  latitude: number,
  longitude: number
): ProjectedLocatorPoint {
  let lon = longitude;
  if (lon > 30 && latitude > 45 && lon > 165) {
    lon -= 360; // Western Aleutians across 180° meridian
  }
  const phi = Math.max(-89.9, Math.min(89.9, latitude)) * DEG2RAD;
  const lam = Math.max(-195, Math.min(40, lon)) * DEG2RAD;
  const theta = ALBERS_N * (lam - LON0);
  const rho =
    Math.sqrt(Math.max(0, ALBERS_C - 2 * ALBERS_N * Math.sin(phi))) / ALBERS_N;
  const rawX = rho * Math.sin(theta);
  const rawY = -(ALBERS_RHO0 - rho * Math.cos(theta));

  const x = ((rawX - X_MIN) / X_SPAN) * LOCATOR_MAP_WIDTH;
  const y = ((rawY - Y_MIN) / Y_SPAN) * LOCATOR_MAP_HEIGHT;

  const pad = 18;
  const inFrame =
    longitude >= -178 &&
    longitude <= -45 &&
    latitude >= 12 &&
    latitude <= 74 &&
    x >= 6 &&
    x <= LOCATOR_MAP_WIDTH - 6 &&
    y >= 6 &&
    y <= LOCATOR_MAP_HEIGHT - 6;

  return {
    x,
    y,
    inFrame,
    clampedX: Math.max(pad, Math.min(LOCATOR_MAP_WIDTH - pad, x)),
    clampedY: Math.max(pad, Math.min(LOCATOR_MAP_HEIGHT - pad, y)),
  };
}

