const parsedRingsCache = new Map<SpeciesId, number[][][]>();

function getParsedSpeciesRings(species: SpeciesId): number[][][] {
  const hit = parsedRingsCache.get(species);
  if (hit) return hit;

  const d = SPECIES_NATIVE_RANGE_PATH[species];
  const rings: number[][][] = [];
  const subpaths = d.split('Z');
  for (const sub of subpaths) {
    const trimmed = sub.trim();
    if (!trimmed) continue;
    const coords = trimmed.replace(/^M/, '').split('L');
    const ring: number[][] = [];
    for (const pair of coords) {
      const spaceIdx = pair.indexOf(' ');
      if (spaceIdx > 0) {
        ring.push([
          Number(pair.slice(0, spaceIdx)),
          Number(pair.slice(spaceIdx + 1)),
        ]);
      }
    }
    if (ring.length >= 3) rings.push(ring);
  }
  parsedRingsCache.set(species, rings);
  return rings;
}

function pointToSegmentDistSq(
  px: number,
  py: number,
  x1: number,
  y1: number,
  x2: number,
  y2: number
): number {
  let x = x1;
  let y = y1;
  const dx = x2 - x;
  const dy = y2 - y;
  if (dx !== 0 || dy !== 0) {
    const t = ((px - x) * dx + (py - y) * dy) / (dx * dx + dy * dy);
    if (t > 1) {
      x = x2;
      y = y2;
    } else if (t > 0) {
      x += dx * t;
      y += dy * t;
    }
  }
  const ex = px - x;
  const ey = py - y;
  return ex * ex + ey * ey;
}

/**
 * Determines whether a geographic coordinate lies within (or within ~15 km of the
 * generalized 1:10M boundary of) the species' native North American range.
 */
export function isWithinSpeciesNativeRange(
  species: SpeciesId,
  latitude: number,
  longitude: number
): boolean {
  const pt = projectToLocatorMap(latitude, longitude);
  if (!pt.inFrame) return false;

  const rings = getParsedSpeciesRings(species);
  let inside = false;
  const edgeToleranceSq = 3.2 * 3.2; // ~15 km boundary generalization tolerance

  for (const ring of rings) {
    const n = ring.length;
    if (n < 3) continue;
    for (let i = 0, j = n - 1; i < n; j = i++) {
      const xi = ring[i][0];
      const yi = ring[i][1];
      const xj = ring[j][0];
      const yj = ring[j][1];

      if (pointToSegmentDistSq(pt.x, pt.y, xi, yi, xj, yj) <= edgeToleranceSq) {
        return true;
      }

      const intersect =
        yi > pt.y !== yj > pt.y &&
        pt.x < ((xj - xi) * (pt.y - yi)) / (yj - yi) + xi;
      if (intersect) inside = !inside;
    }
  }

  return inside;
}
